-- Etapa 12.1: consultas sob RLS; exportação explícita e auditada.
CREATE SCHEMA reporting;REVOKE ALL ON SCHEMA reporting FROM PUBLIC;GRANT USAGE ON SCHEMA reporting TO invictus_auth;
ALTER TABLE access.roles DROP CONSTRAINT role_permission_catalog;
ALTER TABLE access.roles ADD CONSTRAINT role_permission_catalog CHECK(permissions <@ ARRAY['reports.read','reports.export','crm.read','crm.manage','crm.credit','crm.loyalty','orders.read','orders.manage','deliveries.manage','fiscal.read','fiscal.manage','fiscal.issue','fiscal.cancel','finance.read','finance.manage','finance.settle','finance.reverse','finance.cash','pos.read','pos.sell','pos.cash','pos.cash.manage','pos.discount','pos.refund','suppliers.read','suppliers.manage','purchases.read','purchases.manage','purchases.approve','purchases.receive','products.read','products.manage','stock.read','stock.manage','audit.read','organizations.read','organizations.manage','users.read','users.manage','roles.manage','ownership.manage']::text[]);
ALTER TABLE access.roles ADD CONSTRAINT reports_dependencies CHECK((NOT 'reports.read'=ANY(permissions) OR 'organizations.read'=ANY(permissions)) AND (NOT 'reports.export'=ANY(permissions) OR 'reports.read'=ANY(permissions)));
ALTER TABLE access.roles NO FORCE ROW LEVEL SECURITY;UPDATE access.roles SET permissions=permissions||ARRAY['reports.read','reports.export']::text[] WHERE system AND name='Administrador';ALTER TABLE access.roles FORCE ROW LEVEL SECURITY;
ALTER TABLE audit.events DROP CONSTRAINT events_category_check;ALTER TABLE audit.events ADD CONSTRAINT events_category_check CHECK(category IN('organizations','users','permissions','invitations','security','context','products','inventory','suppliers','purchases','sales','cash','finance','fiscal','customers','reports'));
CREATE FUNCTION reporting.record_export(input jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE net uuid:=identity.current_auth_tenant_id();branch uuid;units uuid[];permission text;who text;k text:=input->>'kind';src text:=input->>'source';BEGIN
 IF k NOT IN('transactions','products','units','sellers','cashflow','receivables','payables','closings','stock','purchases','losses') OR k IS NULL OR src NOT IN('manual','sandbox') OR src IS NULL OR length(input::text)>10000 OR jsonb_typeof(input->'rows') IS DISTINCT FROM 'number' OR (input->>'rows')::integer NOT BETWEEN 0 AND 5000 THEN RAISE EXCEPTION 'Exportação inválida' USING ERRCODE='23514';END IF;
 SELECT array_agg(value::uuid) INTO units FROM jsonb_array_elements_text(input->'unitIds');IF cardinality(units) IS NULL OR cardinality(units) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Escopo inválido' USING ERRCODE='42501';END IF;
 permission:=CASE WHEN k IN('transactions','products','units','sellers') THEN CASE WHEN src='manual' THEN 'orders.read' ELSE 'pos.read' END WHEN k IN('cashflow','receivables','payables','closings') THEN 'finance.read' WHEN k='purchases' THEN 'purchases.read' ELSE 'stock.read' END;
 FOREACH branch IN ARRAY units LOOP IF NOT inventory.allowed(net,'reports.export',branch) OR NOT inventory.allowed(net,'reports.read',branch) OR NOT inventory.allowed(net,permission,branch) THEN RAISE EXCEPTION 'Exportação não autorizada' USING ERRCODE='42501';END IF;END LOOP;
 SELECT display_name INTO who FROM identity.users WHERE id=identity.current_auth_actor_id();
 INSERT INTO audit.events(tenant_id,unit_id,actor_id,actor_name,target_label,category,entity_type,action,after_data,request_id) VALUES(net,CASE WHEN cardinality(units)=1 THEN units[1] ELSE NULL END,identity.current_auth_actor_id(),who,'Relatório gerencial','reports','management_report','report.exported',jsonb_build_object('report_kind',k,'source',src,'from',input->>'from','to',input->>'to','unit_ids',to_jsonb(units),'category',input->>'category','supplier_id',input->>'supplierId','status',input->>'status','rows',(input->>'rows')::integer),nullif(current_setting('app.audit_request_id',true),'')::uuid);
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA reporting FROM PUBLIC;GRANT EXECUTE ON FUNCTION reporting.record_export(jsonb) TO invictus_auth;
CREATE INDEX report_crm_fulfilled ON crm.orders(tenant_id,unit_id,((fulfilled_at AT TIME ZONE 'America/Fortaleza')::date)) WHERE fulfilled_at IS NOT NULL;
CREATE INDEX report_crm_returned ON crm.orders(tenant_id,unit_id,((returned_at AT TIME ZONE 'America/Fortaleza')::date)) WHERE returned_at IS NOT NULL;
CREATE INDEX report_pos_confirmed ON pos.sales(tenant_id,unit_id,((confirmed_at AT TIME ZONE 'America/Fortaleza')::date)) WHERE confirmed_at IS NOT NULL;
CREATE INDEX report_pos_returned ON pos.sales(tenant_id,unit_id,((returned_at AT TIME ZONE 'America/Fortaleza')::date)) WHERE returned_at IS NOT NULL;
CREATE INDEX report_physical_moves ON inventory.movements(tenant_id,unit_id,product_id,created_at) WHERE physical_delta<>0;
CREATE INDEX report_receipts_dates ON purchasing.receipts(tenant_id,unit_id,created_at);
